      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "origins", label: "Origins" },
            { id: "ports", label: "Ports" },
            { id: "balance", label: "Exportable supply" },
            { id: "path", label: "Share path" },
          ]}
        />
        <ToggleGroup
          label="Crop"
          value={crop}
          onChange={setCrop}
          options={[
            { id: "soy", label: "Soybeans" },
            { id: "corn", label: "Corn" },
          ]}
        />
      </div>

      {view === "origins" && (
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          <ChartCard
            title={`${crop === "soy" ? "Soybean" : "Corn"} export origins`}
            subtitle="WASDE 2026/27 export Mt ?? share of world trade"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={origins.map((o) => ({
                    name: o.label.replace("United States", "US"),
                    mt: o.mt,
                    share: o.sharePct,
                  }))}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} unit=" Mt" />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={88}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v: number, key: string) =>
                      key === "mt" ? [`${fmtMt(v)} Mt`, "Exports"] : [fmtPct(v), "Share"]
                    }
                  />
                  <Bar dataKey="mt" fill={accent} radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Import absorption"
            subtitle="Desk share of world import demand (PSD / COMTRADE framing)"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={destPie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={52}
                    outerRadius={96}
                    paddingAngle={2}
                  >
                    {destPie.map((_, i) => (
                      <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v: number) => [fmtPct(v), "Share"]} />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Cumulative Top-k origin share"
            subtitle="How fast concentration stacks as exporters are added"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart
                  data={cumulative.map((c) => ({
                    k: `Top-${c.k}`,
                    share: c.sharePct,
                    who: c.label,
                  }))}
                  margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="k" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v: number) => [fmtPct(v), "Cumulative share"]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.who
                        ? String(payload[0].payload.who)
                        : ""
                    }
                  />
                  <Area
                    type="monotone"
                    dataKey="share"
                    stroke={NAVY}
                    fill={accent}
                    fillOpacity={0.35}
                    strokeWidth={2}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Port ?? origin concentration"
            subtitle="National origin share (x) vs port share of world crop (y)"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 8, right: 16, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Origin %"
                    unit="%"
                    tick={{ fontSize: 11 }}
                    domain={[0, "auto"]}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Port/world %"
                    unit="%"
                    tick={{ fontSize: 11 }}
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 280]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v: number, name: string) =>
                      name === "z"
                        ? [`${fmtMt(v)} Mt`, "Port flow"]
                        : [fmtPct(v), name === "x" ? "Origin share" : "Port/world"]
                    }
                    labelFormatter={(_, p) => p?.[0]?.payload?.name ?? ""}
                  />
                  <Scatter data={scatter} fill={TEAL} />
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "ports" && (
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          <ChartCard
            title="Load-port chokepoints"
            subtitle="% of national (or complex) export tons through named corridor"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={ports}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={120}
                    tick={{ fontSize: 10 }}
                  />
                  <Tooltip
                    formatter={(v: number, key: string) =>
                      key === "share"
                        ? [fmtPct(v), "National share"]
                        : [`${fmtMt(v)} Mt`, "Approx flow"]
                    }
                  />
                  <Bar dataKey="share" fill={AMBER} radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Approximate corridor tonnage"
            subtitle="Desk Mt through each named chokepoint"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={ports}
                  margin={{ top: 8, right: 16, left: 0, bottom: 48 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    dataKey="name"
                    tick={{ fontSize: 10, angle: -28, textAnchor: "end" }}
                    interval={0}
                    height={60}
                  />
                  <YAxis tick={{ fontSize: 11 }} unit=" Mt" />
                  <Tooltip
                    formatter={(v: number) => [`${fmtMt(v)} Mt`, "Flow"]}
                  />
                  <Bar dataKey="mt" fill={TEAL} radius={[4, 4, 0, 0]} />
                  <Line
                    type="monotone"
                    dataKey="share"
                    stroke={NAVY}
                    strokeWidth={2}
                    dot={{ r: 3 }}
                    yAxisId={0}
                    hide
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-3 text-xs text-slate-500">
              US Gulf ~{HEADLINE.gulfShareOfUsGrainExportsPct}% of US grain exports ?? Santos ~
              {HEADLINE.santosShareOfBrazilSoyExportsPct}% of Brazil soy ?? Ukrainian Black Sea ~
              {HEADLINE.blackSeaShareOfUkraineCornPct}% of Ukraine corn.
            </p>
          </ChartCard>
        </div>
      )}

      {view === "balance" && (
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          <ChartCard
            title="Production ?? domestic use ?? exports"
            subtitle="WASDE-style balance framing (Mt) for top origins"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={balance}
                  margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                  <Bar dataKey="production" name="Production" stackId="a" fill={SLATE} />
                  <Bar dataKey="domestic" name="Domestic use" fill={NAVY} />
                  <Bar dataKey="exports" name="Exports" fill={accent} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Exportable share of production"
            subtitle="Exports ?? production ??? how export-dependent the crop is"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={balance}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={72}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip formatter={(v: number) => [fmtPct(v), "Exportable"]} />
                  <Bar dataKey="exportable" fill={accent} radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "path" && (
        <div className="grid grid-cols-1 gap-6">
          <ChartCard
            title="Top-origin export share path"
            subtitle="Marketing-year shares of world trade (WASDE-carried desk series)"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart
                  data={path}
                  margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 70]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip formatter={(v: number) => [fmtPct(v), ""]} />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                  {crop === "soy" ? (
                    <>
                      <Area
                        type="monotone"
                        dataKey="soyBrazilPct"
                        name="Brazil soy"
                        stroke={SOY}
                        fill={SOY}
                        fillOpacity={0.25}
                        strokeWidth={2}
                      />
                      <Area
                        type="monotone"
                        dataKey="soyUsPct"
                        name="US soy"
                        stroke={CORN}
                        fill={CORN}
                        fillOpacity={0.2}
                        strokeWidth={2}
                      />
                    </>
                  ) : (
                    <>
                      <Line
                        type="monotone"
                        dataKey="cornUsPct"
                        name="US corn"
                        stroke={CORN}
                        strokeWidth={2}
                        dot={{ r: 3 }}
                      />
                      <Line
                        type="monotone"
                        dataKey="cornBrazilPct"
                        name="Brazil corn"
                        stroke={SOY}
                        strokeWidth={2}
                        dot={{ r: 3 }}
                      />
                      <Line
                        type="monotone"
                        dataKey="cornArgentinaPct"
                        name="Argentina corn"
                        stroke={TEAL}
                        strokeWidth={2}
                        dot={{ r: 3 }}
                      />
                    </>
                  )}
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

