const PIE_COLORS = ["#ca8a04", "#15803d", "#0369a1", "#7c3aed", "#be123c", "#64748b", "#0f766e", "#b45309"];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
