          onChange={setView}
          options={[
            { id: "origins", label: "Origins" },
            { id: "ports", label: "Ports" },
            { id: "balance", label: "Exportable supply" },
            { id: "path", label: "Share path" },
          ]}
        />
        <ToggleGroup
          label="Crop"
          value={crop}
          onChange={setCrop}
          options={[
            { id: "soy", label: "Soybeans" },
            { id: "corn", label: "Corn" },
