                  <Bar dataKey="domestic" name="Domestic use" fill={NAVY} />
                  <Bar dataKey="exports" name="Exports" fill={accent} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Exportable share of production"
            subtitle="Exports ?? production ??? how export-dependent the crop is"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={balance}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={72}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip formatter={(v) => [fmtPct(Number(v)), "Exportable"]} />
                  <Bar dataKey="exportable" fill={accent} radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "path" && (
        <div className="grid grid-cols-1 gap-6">
          <ChartCard
            title="Top-origin export share path"
            subtitle="Marketing-year shares of world trade (WASDE-carried desk series)"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={path}
                  margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 70]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip formatter={(v) => [fmtPct(Number(v)), ""]} />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                  {crop === "soy" ? (
                    <>
                      <Area
                        type="monotone"
                        dataKey="soyBrazilPct"
                        name="Brazil soy"
                        stroke={SOY}
                        fill={SOY}
                        fillOpacity={0.25}
                        strokeWidth={2}
                      />
                      <Area
                        type="monotone"
                        dataKey="soyUsPct"
                        name="US soy"
                        stroke={CORN}
                        fill={CORN}
                        fillOpacity={0.2}
                        strokeWidth={2}
                      />
                    </>
                  ) : (
                    <>
                      <Line
                        type="monotone"
                        dataKey="cornUsPct"
                        name="US corn"
                        stroke={CORN}
                        strokeWidth={2}
                        dot={{ r: 3 }}
                      />
                      <Line
                        type="monotone"
                        dataKey="cornBrazilPct"
                        name="Brazil corn"
                        stroke={SOY}
                        strokeWidth={2}
                        dot={{ r: 3 }}
                      />
                      <Line
                        type="monotone"
                        dataKey="cornArgentinaPct"
                        name="Argentina corn"
                        stroke={TEAL}
                        strokeWidth={2}
                        dot={{ r: 3 }}
                      />
                    </>
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}
